<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { actualizarExpediente, crearExpediente, eliminarExpediente, listarExpedientes, type Expediente, type ExpedientePayload, type Option } from '../services/expedientes'

const filters = reactive({ criterio: '', estado: '', tipoexpediente_id: 0, page: 1 })
const catalogs = reactive({ tipos: [] as Option[], flujos: [] as Option[], motivos: [] as Option[] })
const items = ref<Expediente[]>([])
const pagination = reactive({ current: 1, last: 1, total: 0 })
const loading = ref(false), saving = ref(false), error = ref(''), success = ref(''), formError = ref('')
const modalOpen = ref(false), editingId = ref<number | null>(null)
const form = reactive<ExpedientePayload>({ numero_expediente: '', fecha: '', estado: 1, tipoexpediente_id: 0, flujoatencion_id: 0, motivoexpediente_id: 0 })
const modalTitle = computed(() => editingId.value ? 'Actualizar expediente' : 'Registrar expediente')

async function load(page = 1) {
  filters.page = page; loading.value = true; error.value = ''
  try { const r = await listarExpedientes(filters); items.value = r.data; Object.assign(catalogs, r.catalogs); Object.assign(pagination, { current:r.current_page,last:r.last_page,total:r.total }) }
  catch (cause) { error.value = cause instanceof Error ? cause.message : 'No se pudieron cargar los expedientes.' }
  finally { loading.value = false }
}
function clearFilters(){ Object.assign(filters,{criterio:'',estado:'',tipoexpediente_id:0}); void load() }
function openCreate(){ editingId.value=null; Object.assign(form,{numero_expediente:'',fecha:new Date().toISOString().slice(0,10),estado:1,tipoexpediente_id:0,flujoatencion_id:0,motivoexpediente_id:0}); formError.value=''; modalOpen.value=true }
function openEdit(item:Expediente){ editingId.value=item.id; Object.assign(form,{numero_expediente:item.numero_expediente,fecha:item.fecha?.slice(0,10),estado:item.estado,tipoexpediente_id:item.tipoexpediente_id,flujoatencion_id:item.flujoatencion_id,motivoexpediente_id:item.motivoexpediente_id}); formError.value='';modalOpen.value=true }
async function save(){
  if(!form.numero_expediente||!form.fecha||!form.tipoexpediente_id||!form.flujoatencion_id||!form.motivoexpediente_id){formError.value='Completa todos los campos obligatorios.';return}
  saving.value=true;formError.value=''
  try{const payload={...form,numero_expediente:form.numero_expediente.trim().toUpperCase()};if(editingId.value){await actualizarExpediente(editingId.value,payload);success.value='Expediente actualizado correctamente.'}else{await crearExpediente(payload);success.value='Expediente registrado correctamente.'}modalOpen.value=false;await load(editingId.value?filters.page:1)}
  catch(cause){formError.value=cause instanceof Error?cause.message:'No se pudo guardar el expediente.'}finally{saving.value=false}
}
async function remove(item:Expediente){if(!confirm(`¿Eliminar el expediente “${item.numero_expediente}”?`))return;try{await eliminarExpediente(item.id);success.value='Expediente eliminado correctamente.';await load(filters.page)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo eliminar el expediente.'}}
function name(option?:Option|null){return option?.nombre||'—'}
onMounted(()=>load())
</script>

<template>
<div class="page">
  <nav class="breadcrumbs"><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/comercial">Comercial</RouterLink> / <RouterLink to="/modulos/comercial/comercializacion">Comercialización</RouterLink> / Expedientes</nav>
  <header class="page-header"><div class="title-icon">EV</div><div><small>Atención comercial</small><h1>Expedientes</h1><p>Registro y seguimiento de expedientes comerciales.</p></div><strong v-if="pagination.total">{{pagination.total}} registros</strong><button @click="openCreate">＋ Nuevo expediente</button></header>
  <div v-if="success" class="flash"><b>✓</b>{{success}}<button @click="success=''">×</button></div>
  <form class="filters" @submit.prevent="load()"><div class="filter-title"><b>⌕ Buscar expedientes</b><small>Consulta por número, tipo o estado.</small></div><div class="filter-grid"><label><span>Número de expediente</span><input v-model.trim="filters.criterio" placeholder="Buscar por número…"></label><label><span>Tipo</span><select v-model="filters.tipoexpediente_id"><option :value="0">Todos</option><option v-for="o in catalogs.tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Estado</span><select v-model="filters.estado"><option value="">Todos</option><option value="1">Activo</option><option value="0">Inactivo</option></select></label><div class="actions"><button type="submit">Buscar</button><button type="button" class="clear" @click="clearFilters">Limpiar</button></div></div></form>
  <div v-if="error" class="notice error"><b>No se pudo obtener el listado.</b><span>{{error}}</span><button @click="load(filters.page)">Reintentar</button></div><div v-else-if="loading" class="notice"><span class="spinner"></span>Cargando expedientes…</div><div v-else-if="!items.length" class="notice"><b>No se encontraron expedientes</b><span>Modifica los filtros o registra uno nuevo.</span></div>
  <section v-else class="cards"><article v-for="item in items" :key="item.id" class="card"><header><span>▤</span><div><small>Expediente</small><h2>{{item.numero_expediente}}</h2></div><em :class="{off:!item.estado}">{{item.estado?'Activo':'Inactivo'}}</em></header><dl><div><dt>Fecha</dt><dd>{{item.fecha?.slice(0,10)||'—'}}</dd></div><div><dt>Tipo</dt><dd>{{name(item.tipo_expediente)}}</dd></div><div><dt>Motivo</dt><dd>{{name(item.motivo)}}</dd></div><div><dt>Flujo</dt><dd>{{name(item.flujo)}}</dd></div><div><dt>Trabajos</dt><dd>{{item.trabajos_count??0}}</dd></div></dl><footer><button class="edit" @click="openEdit(item)">Editar</button><button class="delete" @click="remove(item)">Eliminar</button></footer></article></section>
  <footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer>
  <div v-if="modalOpen" class="backdrop" @mousedown.self="modalOpen=false"><section class="modal"><header><div class="modal-icon">▤</div><div><small>Atención comercial</small><h2>{{modalTitle}}</h2></div><button @click="modalOpen=false">×</button></header><form @submit.prevent="save"><div v-if="formError" class="form-error">{{formError}}</div><div class="form-grid"><label><span>Número *</span><input v-model.trim="form.numero_expediente" maxlength="100" placeholder="Número de expediente"></label><label><span>Fecha *</span><input v-model="form.fecha" type="date"></label><label><span>Estado *</span><select v-model="form.estado"><option :value="1">Activo</option><option :value="0">Inactivo</option></select></label><label><span>Tipo de expediente *</span><select v-model="form.tipoexpediente_id"><option :value="0">Seleccione…</option><option v-for="o in catalogs.tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Motivo *</span><select v-model="form.motivoexpediente_id"><option :value="0">Seleccione…</option><option v-for="o in catalogs.motivos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Flujo *</span><select v-model="form.flujoatencion_id"><option :value="0">Seleccione…</option><option v-for="o in catalogs.flujos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label></div><footer><button type="button" class="cancel" @click="modalOpen=false">Cancelar</button><button type="submit" :disabled="saving">{{saving?'Guardando…':editingId?'Actualizar':'Registrar'}}</button></footer></form></section></div>
</div>
</template>

<style scoped>
