#647179;border-color:#d5ddda;background:#fff}.notice{min-height:145px;padding:28px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;border:1px dashed #ccd7d2;border-radius:11px;color:#748188;background:#fff;font-size:.74rem}.notice.error{color:#9d3b3b;border-color:#efcaca}.spinner{width:25px;height:25px;border:2px solid #cde7dc;border-top-color:var(--green);border-radius:50%;animation:spin .7s linear infinite}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.card{overflow:hidden;border:1px solid #dce7e2;border-radius:11px;background:#fff}.card>header{padding:15px 16px;display:flex;align-items:center;gap:10px;color:#fff;background:var(--green)}.card header small{font-size:.57rem;opacity:.8}.card h2{margin:2px 0 0;font-size:.87rem}.card header em{margin-left:auto;padding:4px 7px;border-radius:12px;color:#176a4d;background:#dff4eb;font-size:.56rem;font-style:normal}.card header em.off{color:#765c22;background:#fff1c9}.card dl{margin:0;padding:13px 16px}.card dl>div{padding:6px 0;display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #f0f3f2;font-size:.65rem}.card dt{color:#89958f}.card dd{margin:0;text-align:right}.card>footer{padding:0 16px 16px;display:flex;gap:7px}.card>footer button{flex:1;padding:9px;border:0;border-radius:7px;color:#fff;font-size:.64rem}.edit{background:var(--green)}.delete{background:#c65757}.pagination{padding:20px;display:flex;justify-content:center;align-items:center;gap:15px}.pagination span{font-size:.7rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#152d2488}.modal{width:min(100%,650px);border-radius:14px;background:#fff;box-shadow:0 22px 70px #10251d55}.modal>header{padding:19px 22px;display:flex;align-items:center;gap:12px;border-bottom:1px solid #e9eeec}.modal h2{margin:2px 0;font-size:1.05rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.5rem}.modal form{padding:22px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.form-error{margin-bottom:15px;padding:11px;border:1px solid #efcaca;border-radius:7px;color:#a43d3d;background:#fff5f5;font-size:.68rem}.modal form>footer{margin-top:21px;display:flex;justify-content:flex-end;gap:8px}.modal form>footer button{padding:10px 16px;border:0;border-radius:7px;color:#fff;background:var(--green);font-size:.7rem}.modal form>footer .cancel{color:#63716b;background:#e9eeec}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1050px){.cards{grid-template-columns:repeat(2,1fr)}.filter-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.page-header{flex-wrap:wrap;align-items:flex-start}.page-header>strong{display:none}.page-header>button{width:100%}.cards,.filter-grid,.form-grid{grid-template-columns:1fr}.actions{flex-direction:column}}
</style>
